-- PT120-S1-Q25. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT120-S1-Q25$batch07$ AND q.stimulus=$batch07$Claude: Because of the relatively high number of middle-aged people in the workforce, there will be fewer opportunities for promotion into upper-management positions. Since this will decrease people’s incentive to work hard, economic productivity and the quality of life will diminish.
Thelma: This glut of middle-aged workers will lead many people to form their own companies. They will work hard and thus increase economic productivity, improving the quality of life even if many of the companies ultimately fail.$batch07$ AND q.prompt=$batch07$On the basis of their statements, Claude and Thelma are committed to agreeing about which one of the following?$batch07$ AND q.correct_choice=$batch07$E$batch07$) THEN RAISE EXCEPTION 'Question changed: PT120-S1-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT120-S1-Q25$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S1-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT120-S1-Q25$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Claude's Position$batch07$, $batch07$So many middle-aged workers means fewer promotions, less incentive, and so lower productivity and quality of life.$batch07$), (1, $batch07$Thelma's Position$batch07$, $batch07$The glut of middle-aged workers will push people to start companies. They will work hard and raise productivity and quality of life.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$This one asks what they *agree* on. They predict opposite results, but they share a starting point: the large number of middle-aged workers will change productivity. Claude says down; Thelma says up. Either way, it has an effect.$batch07$), (3, $batch07$Goal$batch07$, $batch07$That the number of middle-aged workers will affect economic productivity.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT120-S1-Q25$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Thelma says productivity improves quality of life, which runs the other way from A. Claude says both will fall but never says quality of life drives productivity. Neither commits to A.$batch07$), ($batch07$B$batch07$, $batch07$Thelma says productivity rises "even if many of the companies ultimately fail", so Thelma would accept B. Claude never talks about companies failing.$batch07$), ($batch07$C$batch07$, $batch07$Claude ties hard work to promotion chances. Thelma's workers work hard in companies they founded, so Thelma isn't committed to C, and may reject it.$batch07$), ($batch07$D$batch07$, $batch07$This is the most popular wrong answer. Both speakers describe a large number of middle-aged workers *now* ("relatively high number", "this glut"). Neither says the number will increase.$batch07$), ($batch07$E$batch07$, $batch07$Claude: the number of middle-aged workers will lower productivity. Thelma: it will raise productivity. Both say it will affect productivity.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT120-S1-Q25$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
